python -m py_compile src/services/payments.py && python - <<'EOF'
import sys
sys.path.insert(0, 'src')
from decimal import Decimal
from services.payments import refund_payment, Payment, RefundError

class Repo:
    def __init__(self, payment):
        self.payment = payment
        self.saved = None
    def get_payment(self, payment_id):
        return self.payment
    def save_refund(self, payment, amount, gateway_refund_id):
        self.saved = (payment, amount, gateway_refund_id)

class UoW:
    def __enter__(self):
        return self
    def __exit__(self, *exc):
        if exc[0] is None:
            self.committed = True

class Gateway:
    def __init__(self):
        self.calls = []
    def refund(self, payment_id, amount):
        self.calls.append((payment_id, amount))
        return "gw-1"

class Notifier:
    def __init__(self):
        self.sent = []
    def refund_completed(self, payment_id, amount):
        self.sent.append((payment_id, amount))

p = Payment(id="p1", status="captured", amount=Decimal("10.00"), refunded_amount=Decimal("0"))
repo, uow, gw, notifier = Repo(p), UoW(), Gateway(), Notifier()
result = refund_payment("p1", None, repo, uow, gw, notifier)
assert result == Decimal("10.00")
assert repo.saved[2] == "gw-1"
assert uow.committed and notifier.sent == [("p1", Decimal("10.00"))]

try:
    refund_payment("p1", Decimal("99"), repo, uow, gw, notifier)
    raise SystemExit("expected RefundError")
except RefundError:
    pass

p.status = "void"
try:
    refund_payment("p1", None, repo, uow, gw, notifier)
    raise SystemExit("expected RefundError")
except RefundError:
    pass
print("ok")
EOF

